import pytest
import torch

from comfy.cli_args import args

# Must precede the import: comfy.model_management picks its device at import time, and a CUDA
# build with no driver raises there.
_original_cpu = args.cpu
if not torch.cuda.is_available():
    args.cpu = True
try:
    import main
finally:
    args.cpu = _original_cpu

class LoopEscape(Exception):
    pass


class Queue:
    def __init__(
        self,
        completion_error: RuntimeError | None = None,
        queued_after_first: int = 1,
        on_second_get=None,
    ) -> None:
        self.completion_error = completion_error
        # Prompts still waiting once the first is taken; tests opt in to an idle queue.
        self.queued = queued_after_first
        self.running = 0
        self.on_second_get = on_second_get
        self.get_calls = 0

    def get(self, timeout=None):
        self.get_calls += 1
        if self.get_calls > 1:
            if self.on_second_get is not None:
                self.on_second_get()
            raise LoopEscape("prompt worker requested a second item")
        self.running = 1
        return (0, "prompt-id", {}, {}, [], {}), 1

    def get_tasks_remaining(self) -> int:
        # Like PromptQueue: queued plus running, and the running prompt only leaves in task_done.
        return self.queued + self.running

    def task_done(self, *args, **kwargs) -> None:
        if self.completion_error is not None:
            raise self.completion_error
        self.running = 0

    def get_flags(self):
        return {}


class Server:
    last_prompt_id = None
    client_id = None


class AssetManager:
    def __init__(self, resume_error: RuntimeError | None = None) -> None:
        self.paused = False
        self.resume_error = resume_error

    def pause_background_scan(self) -> None:
        self.paused = True

    def resume_background_scan(self) -> None:
        self.paused = False
        if self.resume_error is not None:
            raise self.resume_error


class Executor:
    def __init__(self, *args, **kwargs) -> None:
        self.history_result = {}
        self.success = True
        self.status_messages = []

    def execute(self, *args, **kwargs) -> None:
        return None


class ExecuteFailureExecutor(Executor):
    def execute(self, *args, **kwargs) -> None:
        raise RuntimeError("forced execute failure")


def test_prompt_worker_resumes_background_scan_when_execute_raises(monkeypatch) -> None:
    monkeypatch.setattr(main.execution, "PromptExecutor", ExecuteFailureExecutor)
    asset_manager = AssetManager()

    with pytest.raises(RuntimeError, match="^forced execute failure$"):
        main.prompt_worker(Queue(), Server(), asset_manager)

    assert asset_manager.paused is False


def test_prompt_worker_resumes_background_scan_when_completion_raises(monkeypatch) -> None:
    monkeypatch.setattr(main.execution, "PromptExecutor", Executor)
    asset_manager = AssetManager()

    with pytest.raises(RuntimeError, match="^forced completion failure$"):
        main.prompt_worker(
            Queue(completion_error=RuntimeError("forced completion failure")),
            Server(),
            asset_manager,
        )

    assert asset_manager.paused is False


def test_prompt_worker_preserves_execute_error_when_resume_raises(monkeypatch) -> None:
    monkeypatch.setattr(main.execution, "PromptExecutor", ExecuteFailureExecutor)
    asset_manager = AssetManager(resume_error=RuntimeError("forced resume failure"))

    with pytest.raises(RuntimeError, match="^forced execute failure$"):
        main.prompt_worker(Queue(), Server(), asset_manager)

    assert asset_manager.paused is False


def test_prompt_worker_resumes_scan_when_later_iteration_raises_before_gc(monkeypatch) -> None:
    monkeypatch.setattr(main.execution, "PromptExecutor", Executor)
    clock = iter((1.0, 2.0, 2.0))
    monkeypatch.setattr(main.time, "perf_counter", lambda: next(clock))
    asset_manager = AssetManager()
    queue = Queue()

    with pytest.raises(LoopEscape, match="^prompt worker requested a second item$"):
        main.prompt_worker(queue, Server(), asset_manager)

    assert queue.get_calls == 2
    assert asset_manager.paused is False


def _paused_when_the_worker_asks_for_the_next_prompt(monkeypatch, queued_after_first: int) -> list[bool]:
    monkeypatch.setattr(main.execution, "PromptExecutor", Executor)
    # The clock never reaches the 10 s GC interval, so only the idle check can resume the scan.
    monkeypatch.setattr(main.time, "perf_counter", lambda: 1.0)
    asset_manager = AssetManager()
    seen: list[bool] = []
    queue = Queue(queued_after_first=queued_after_first, on_second_get=lambda: seen.append(asset_manager.paused))

    with pytest.raises(LoopEscape, match="^prompt worker requested a second item$"):
        main.prompt_worker(queue, Server(), asset_manager)

    return seen


def test_prompt_worker_resumes_scan_once_the_queue_is_empty(monkeypatch) -> None:
    assert _paused_when_the_worker_asks_for_the_next_prompt(monkeypatch, queued_after_first=0) == [False]


def test_prompt_worker_keeps_scan_paused_while_prompts_are_queued(monkeypatch) -> None:
    assert _paused_when_the_worker_asks_for_the_next_prompt(monkeypatch, queued_after_first=1) == [True]

import math

import av
import numpy as np
import pytest
import torch

from comfy.cli_args import args

if not torch.cuda.is_available():
    args.cpu = True

from comfy_api_nodes.util.conversions import audio_input_to_mp3  # noqa: E402

SAMPLE_RATE = 48000
DURATION = 2.0
LEFT_HZ = 440.0
RIGHT_HZ = 880.0


def tone(freq, duration=DURATION, sample_rate=SAMPLE_RATE):
    t = torch.arange(int(sample_rate * duration), dtype=torch.float32) / sample_rate
    return 0.5 * torch.sin(2 * math.pi * freq * t)


@pytest.fixture
def stereo_audio():
    """Comfy AUDIO with two tones that stay distinguishable through mp3."""
    waveform = torch.stack([tone(LEFT_HZ), tone(RIGHT_HZ)]).unsqueeze(0)
    return {"waveform": waveform, "sample_rate": SAMPLE_RATE}


@pytest.fixture
def mono_audio():
    return {"waveform": tone(LEFT_HZ).unsqueeze(0).unsqueeze(0), "sample_rate": SAMPLE_RATE}


def decode(buffer):
    """(planes[C, N], sample_rate, channels) of an encoded mp3 buffer"""
    buffer.seek(0)
    with av.open(buffer, mode="r") as container:
        stream = container.streams.audio[0]
        planes = []
        for frame in container.decode(audio=0):
            array = frame.to_ndarray()
            if frame.format.is_planar:
                planes.append(array)
            else:
                planes.append(array.reshape(-1, len(frame.layout.channels)).T)
        return np.concatenate(planes, axis=1), stream.codec_context.sample_rate, len(stream.layout.channels)


def dominant_hz(signal, sample_rate):
    """Peak frequency, ignoring the encoder's padding at either edge"""
    edge = int(0.2 * sample_rate)
    window = signal[edge:-edge]
    spectrum = np.abs(np.fft.rfft(window * np.hanning(window.size)))
    return np.fft.rfftfreq(window.size, 1.0 / sample_rate)[int(np.argmax(spectrum))]


def test_stereo_duration_is_preserved(stereo_audio):
    planes, sample_rate, channels = decode(audio_input_to_mp3(stereo_audio))
    assert channels == 2
    assert sample_rate == SAMPLE_RATE
    assert planes.shape[1] / sample_rate == pytest.approx(DURATION, abs=0.15)


def test_stereo_channels_are_not_concatenated(stereo_audio):
    """The channels must be interleaved; concatenating them plays the clip twice."""
    planes, sample_rate, _ = decode(audio_input_to_mp3(stereo_audio))
    assert dominant_hz(planes[0], sample_rate) == pytest.approx(LEFT_HZ, abs=15)
    assert dominant_hz(planes[1], sample_rate) == pytest.approx(RIGHT_HZ, abs=15)


def test_mono_duration_is_preserved(mono_audio):
    planes, sample_rate, _ = decode(audio_input_to_mp3(mono_audio))
    assert planes.shape[1] / sample_rate == pytest.approx(DURATION, abs=0.15)
    assert dominant_hz(planes[0], sample_rate) == pytest.approx(LEFT_HZ, abs=15)

import asyncio
import base64
from io import BytesIO

import torch
from PIL import Image

from comfy.cli_args import args

if not torch.cuda.is_available():
    args.cpu = True

from comfy_api_nodes.apis.gemini import (  # noqa: E402
    GeminiCandidate,
    GeminiContent,
    GeminiGenerateContentResponse,
    GeminiInlineData,
    GeminiPart,
)
from comfy_api_nodes.nodes_gemini import get_image_from_response  # noqa: E402


def image_part(mode, color):
    buffer = BytesIO()
    Image.new(mode, (4, 4), color).save(buffer, format="PNG")
    return GeminiPart(
        inlineData=GeminiInlineData(
            data=base64.b64encode(buffer.getvalue()).decode(),
            mimeType="image/png",
        )
    )


def response(*parts):
    return GeminiGenerateContentResponse(
        candidates=[GeminiCandidate(content=GeminiContent(parts=list(parts), role="model"))]
    )


def test_rgb_only_response_stays_three_channels():
    out = asyncio.run(get_image_from_response(response(image_part("RGB", (10, 20, 30)))))
    assert out.shape == (1, 4, 4, 3)


def test_mixed_rgb_and_rgba_parts_are_padded_to_the_same_width():
    out = asyncio.run(
        get_image_from_response(
            response(
                image_part("RGB", (10, 20, 30)),
                image_part("RGBA", (10, 20, 30, 0)),
            )
        )
    )
    assert out.shape == (2, 4, 4, 4)
    # the part that had no alpha is padded opaque, the transparent one is preserved
    assert out[0, ..., 3].min() == 1.0
    assert out[1, ..., 3].max() == 0.0

from io import BytesIO


class SVG:
    """Stores SVG representations via a list of BytesIO objects."""

    def __init__(self, data: list[BytesIO]):
        self.data = data

    def combine(self, other: 'SVG') -> 'SVG':
        return SVG(self.data + other.data)

    @staticmethod
    def combine_all(svgs: list['SVG']) -> 'SVG':
        all_svgs_list: list[BytesIO] = []
        for svg_item in svgs:
            all_svgs_list.extend(svg_item.data)
        return SVG(all_svgs_list)

